const API='api.php?action=';let csrf='';let state={shop:null,categories:[],products:[],repairs:[],sales:[],payments:[]};let currentReport=null;
const $=id=>document.getElementById(id);const fmt=n=>'Rs. '+Number(n||0).toLocaleString('en-PK',{maximumFractionDigits:2});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dateFmt=s=>s?new Date(String(s).replace(' ','T')).toLocaleString():'';const placeholder='data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="300" height="180"><rect width="100%" height="100%" fill="#eef2ff"/><text x="50%" y="52%" font-size="18" text-anchor="middle" fill="#6366f1" font-family="Arial">RepairFlow</text></svg>');
async function api(action,payload=null,files=null,method='POST'){let opts={method,headers:{'X-CSRF-Token':csrf}};if(method==='GET'){opts={method:'GET',headers:{}}}else if(files){let fd=new FormData();Object.entries(payload||{}).forEach(([k,v])=>fd.append(k,v??''));Object.entries(files).forEach(([k,v])=>{if(v)fd.append(k,v)});opts.body=fd;}else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(payload||{});}let res=await fetch(API+action+(method==='GET'&&payload?'&'+new URLSearchParams(payload):''),opts);let out=await res.json().catch(()=>({ok:false,message:'Server returned an invalid response.'}));if(!res.ok||!out.ok)throw new Error(out.message||'Request failed.');if(out.csrf)csrf=out.csrf;return out;}
function toast(message,type='success'){let id='t'+Date.now();$('toastArea').insertAdjacentHTML('beforeend',`<div id="${id}" class="toast border-0 text-bg-${type==='success'?'success':type==='warning'?'warning':'danger'}" role="alert"><div class="d-flex"><div class="toast-body">${esc(message)}</div><button type="button" class="btn-close ${type==='warning'?'':'btn-close-white'} me-2 m-auto" data-bs-dismiss="toast"></button></div></div>`);let el=$(id);let t=new bootstrap.Toast(el,{delay:3500});t.show();el.addEventListener('hidden.bs.toast',()=>el.remove());}
function showAuth(register=false){$('authScreen').classList.remove('hidden');$('appShell').classList.add('hidden');$('loginBox').classList.toggle('hidden',register);$('registerBox').classList.toggle('hidden',!register);$('authMessage').textContent='';}
function showApp(){ $('authScreen').classList.add('hidden');$('appShell').classList.remove('hidden'); }
async function loadState(){let d=await api('bootstrap',null,null,'GET');state={...state,...d};renderAll();showApp();}
async function start(){try{let d=await fetch(API+'csrf').then(r=>r.json());csrf=d.csrf;if(d.loggedIn){await loadState();}else showAuth(false);}catch(e){showAuth(false);toast('Cannot connect to the database. Check config.php and MySQL.','danger');}}
$('showRegister').onclick=e=>{e.preventDefault();showAuth(true)};$('showLogin').onclick=e=>{e.preventDefault();showAuth(false)};
$('loginForm').onsubmit=async e=>{e.preventDefault();try{let d=await api('login',{username:$('loginUser').value,password:$('loginPass').value});csrf=d.csrf;await loadState();toast('Welcome back.');}catch(err){$('authMessage').className='small mt-3 text-danger';$('authMessage').textContent=err.message;}};
$('registerForm').onsubmit=async e=>{e.preventDefault();try{let p={username:$('regUser').value,password:$('regPass').value,shop_name:$('regShop').value,phone:$('regPhone').value};let d=await api('register',p,{logo:$('regLogo').files[0]||null});csrf=d.csrf;await loadState();toast('Shop account created.');}catch(err){$('authMessage').className='small mt-3 text-danger';$('authMessage').textContent=err.message;}};
$('logoutBtn').onclick=async()=>{try{await api('logout',{});}catch(e){}state={shop:null,categories:[],products:[],repairs:[],sales:[],payments:[]};showAuth(false);};$('refreshBtn').onclick=async()=>{try{await loadState();toast('Workspace refreshed.');}catch(e){toast(e.message,'danger')}};
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));function switchView(v){document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id==='view-'+v));document.querySelectorAll('.nav-btn').forEach(el=>el.classList.toggle('active',el.dataset.view===v));}
function renderAll(){renderShop();renderMetrics();renderRepairs();renderCategories();renderProducts();renderSales();renderAlerts();}
function renderShop(){let s=state.shop||{};$('headShopName').textContent=s.shop_name||'RepairFlow Pro';$('headPhone').textContent=s.phone||'';$('headLogo').src=s.logo_path||placeholder;$('settingsName').value=s.shop_name||'';$('settingsPhone').value=s.phone||'';}
function renderMetrics(){let r=state.repairs.reduce((a,x)=>a+Number(x.final_cost||0),0),s=state.sales.reduce((a,x)=>a+Number(x.total||0),0),pending=state.repairs.filter(x=>['Pending','In-Progress'].includes(x.status)).length,out=state.products.filter(x=>Number(x.qty)<=0).length;$('metricRepair').textContent=fmt(r);$('metricSales').textContent=fmt(s);$('metricPending').textContent=pending;$('metricStock').textContent=out;}
function repairActions(r){return `<div class="d-flex flex-wrap gap-1"><button class="btn btn-sm btn-light border" onclick="editRepair(${Number(r.id)})" title="Edit"><i class="fa-solid fa-pen"></i></button><button class="btn btn-sm btn-outline-success" onclick="openPayment(${Number(r.id)})" title="Record payment"><i class="fa-solid fa-money-bill-wave"></i></button><button class="btn btn-sm btn-outline-primary" onclick="invoice(${Number(r.id)})" title="Invoice"><i class="fa-solid fa-file-pdf"></i></button><button class="btn btn-sm btn-outline-danger" onclick="deleteRepair(${Number(r.id)})" title="Delete"><i class="fa-solid fa-trash"></i></button></div>`}
function renderRepairs(){let rows=state.repairs.map(r=>`<tr><td>${r.device_photo?`<img class="repair-thumb mb-2" src="${esc(r.device_photo)}" alt="Device photo" loading="lazy">`:''}<strong>${esc(r.customer_name)}</strong><div class="small-muted">${esc(r.customer_phone)} · ${dateFmt(r.created_at)}</div><div class="small-muted">${esc(r.device_model)}</div></td><td style="min-width:180px;max-width:300px">${esc(r.description)}</td><td><select class="form-select form-select-sm status-select" onchange="changeStatus(${Number(r.id)},this.value)">${['Pending','In-Progress','Completed','Cancelled'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td class="fw-bold">${fmt(r.final_cost)}<div class="small-muted">Est. ${fmt(r.estimated_cost)}</div></td><td><span class="badge ${r.payment_status==='Paid'?'text-bg-success':r.payment_status==='Partial'?'text-bg-warning':'text-bg-secondary'}">${esc(r.payment_status)}</span></td><td>${repairActions(r)}</td></tr>`).join('')||'<tr><td colspan="6" class="text-center text-secondary py-4">No repair tickets yet.</td></tr>';$('repairsTable').innerHTML=rows;$('dashboardRepairs').innerHTML=state.repairs.slice(0,8).map(r=>`<tr><td>${r.device_photo?`<img class="repair-thumb mb-2" src="${esc(r.device_photo)}" alt="Device photo" loading="lazy">`:''}<strong>${esc(r.customer_name)}</strong><div class="small-muted">${esc(r.device_model)} · ${esc(r.customer_phone)}</div></td><td style="max-width:220px">${esc(r.description)}</td><td><select class="form-select form-select-sm status-select" onchange="changeStatus(${Number(r.id)},this.value)">${['Pending','In-Progress','Completed','Cancelled'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td class="fw-bold">${fmt(r.final_cost)}</td><td>${esc(r.payment_status)}</td><td>${repairActions(r)}</td></tr>`).join('')||'<tr><td colspan="6" class="text-center text-secondary py-4">No active repairs. Create your first ticket.</td></tr>';}
function renderCategories(){let opts=state.categories.map(c=>`<option value="${Number(c.id)}">${esc(c.name)}</option>`).join('');$('prodCategory').innerHTML=opts||'<option value="">Add a category first</option>';$('categoryFilter').innerHTML='<option value="all">All categories</option>'+opts;}
function renderProducts(){let filter=$('categoryFilter').value||'all';let ps=state.products.filter(p=>filter==='all'||String(p.category_id||'')===filter);$('productsGrid').innerHTML=ps.map(p=>{let qty=Number(p.qty),low=qty<=Number(p.low_stock_threshold);return `<div class="col-6 col-md-4 col-xxl-3"><div class="product-card"><img class="product-image" src="${esc(p.image_path||placeholder)}" alt="${esc(p.title)}"><div class="product-body"><div class="d-flex justify-content-between align-items-center gap-1 mb-2"><span class="small-muted text-truncate">${esc(p.category_name||'Uncategorized')}</span><button class="btn btn-sm btn-light border" onclick="editProduct(${Number(p.id)})" title="Edit product"><i class="fa-solid fa-pen"></i></button></div><h6 class="fw-bold mb-2" style="font-size:.9rem">${esc(p.title)}</h6><div class="fw-bold text-primary mb-2">${fmt(p.price)}</div><button class="stock-pill border-0 ${qty===0?'bg-danger text-white':low?'bg-warning text-dark':'bg-success-subtle text-success'} mb-3" onclick="openRestock(${Number(p.id)})" title="Click to update stock">${qty===0?'Out of stock':qty+' in stock'} · Restock</button><div class="d-flex gap-1"><button class="btn btn-success btn-sm flex-grow-1" ${qty===0?'disabled':''} onclick="quickSell(${Number(p.id)})"><i class="fa-solid fa-cart-shopping me-1"></i>Sell</button><button class="btn btn-outline-danger btn-sm" onclick="deleteProduct(${Number(p.id)})" title="Delete"><i class="fa-solid fa-trash"></i></button></div><div class="small-muted mt-2">Buy cost ${fmt(p.purchase_cost)}</div></div></div></div>`}).join('')||'<div class="col-12 text-center text-secondary py-5">No products in this category yet.</div>';}
function renderSales(){$('salesTable').innerHTML=state.sales.map(s=>`<tr><td>${dateFmt(s.created_at)}</td><td>${esc(s.product_title)}</td><td>${esc(s.category_name)}</td><td>${Number(s.quantity)}</td><td class="fw-bold text-success">${fmt(s.total)}</td></tr>`).join('')||'<tr><td colspan="5" class="text-center text-secondary py-4">No direct sales recorded yet.</td></tr>';}
function renderAlerts(){let out=state.products.filter(p=>Number(p.qty)<=Number(p.low_stock_threshold));$('stockAlerts').innerHTML=out.map(p=>`<button class="side-alert ${Number(p.qty)===0?'danger':''} w-100 text-start" onclick="openRestock(${Number(p.id)})"><strong>${Number(p.qty)===0?'Out of stock':'Low stock'}:</strong> ${esc(p.title)} <span class="float-end">${Number(p.qty)} left</span></button>`).join('')||'<div class="small-muted">All products have sufficient stock.</div>';let late=state.repairs.filter(r=>['Pending','In-Progress'].includes(r.status)&&r.due_date&&r.due_date<new Date().toISOString().slice(0,10));$('lateAlerts').innerHTML=late.map(r=>`<div class="side-alert"><strong>${esc(r.customer_name)}</strong><div>${esc(r.device_model)}</div><div class="small-muted">Due ${esc(r.due_date)}</div></div>`).join('')||'<div class="small-muted">No overdue repairs.</div>';$('recentCustomers').innerHTML=state.repairs.slice(0,5).map(r=>`<div class="d-flex align-items-center gap-2 mb-3"><div class="avatar">${esc((r.customer_name||'?').charAt(0).toUpperCase())}</div><div class="text-truncate"><div class="fw-semibold text-truncate">${esc(r.customer_name)}</div><div class="small-muted text-truncate">${esc(r.device_model)}</div></div></div>`).join('')||'<div class="small-muted">No customer records yet.</div>';}
$('categoryForm').onsubmit=async e=>{e.preventDefault();try{await api('category',{name:$('categoryName').value});$('categoryName').value='';await loadState();toast('Category added.')}catch(err){toast(err.message,'danger')}};$('categoryFilter').onchange=renderProducts;
$('productForm').onsubmit=async e=>{e.preventDefault();try{let payload={id:$('productId').value,title:$('prodTitle').value,category_id:$('prodCategory').value,price:$('prodPrice').value,purchase_cost:$('prodCost').value,qty:$('prodQty').value,low_stock_threshold:$('prodThreshold').value};await api('product_save',payload,{image:$('prodImage').files[0]||null});resetProductForm();await loadState();toast('Product saved.')}catch(err){toast(err.message,'danger')}};
function resetProductForm(){$('productForm').reset();$('productId').value='';$('productFormTitle').textContent='Add inventory product';$('prodThreshold').value=2;} $('cancelProductEdit').onclick=resetProductForm;
function editProduct(id){let p=state.products.find(x=>Number(x.id)===id);if(!p)return;$('productId').value=p.id;$('prodTitle').value=p.title;$('prodCategory').value=p.category_id||'';$('prodPrice').value=p.price;$('prodCost').value=p.purchase_cost;$('prodQty').value=p.qty;$('prodThreshold').value=p.low_stock_threshold;$('productFormTitle').textContent='Edit inventory product';switchView('catalog');$('productForm').scrollIntoView({behavior:'smooth',block:'center'});}
async function deleteProduct(id){let p=state.products.find(x=>Number(x.id)===id);if(!p||!confirm(`Delete "${p.title}" from inventory? Past sales records will remain.`))return;try{await api('product_delete',{id});await loadState();toast('Product deleted.')}catch(e){toast(e.message,'danger')}}
const restockModal=new bootstrap.Modal($('restockModal'));function openRestock(id){let p=state.products.find(x=>Number(x.id)===id);if(!p)return;$('restockProductId').value=id;$('restockProductName').textContent=`${p.title} · Current stock: ${p.qty}`;$('restockQty').value=1;$('restockCost').value=p.purchase_cost||0;$('restockNote').value='';restockModal.show();}$('restockForm').onsubmit=async e=>{e.preventDefault();try{await api('restock',{id:$('restockProductId').value,qty:$('restockQty').value,purchase_cost:$('restockCost').value,note:$('restockNote').value});restockModal.hide();await loadState();toast('Stock updated successfully.')}catch(err){toast(err.message,'danger')}};
async function quickSell(id){let p=state.products.find(x=>Number(x.id)===id);if(!p||Number(p.qty)<1)return;let q=prompt(`How many "${p.title}" units to sell? Available: ${p.qty}`,'1');if(q===null)return;if(!/^\d+$/.test(q)||Number(q)<1||Number(q)>Number(p.qty)){toast('Enter a valid quantity within available stock.','danger');return;}try{await api('sell',{id,qty:Number(q)});await loadState();toast('Sale recorded and stock reduced.')}catch(e){toast(e.message,'danger')}}
$('repairForm').onsubmit=async e=>{e.preventDefault();try{let p={id:$('repairId').value,customer_name:$('repName').value,customer_phone:$('repPhone').value,device_model:$('repModel').value,description:$('repDescription').value,estimated_cost:$('repEstimate').value,final_cost:$('repFinal').value,due_date:$('repDue').value};await api('repair_save',p,{photo:$('repPhoto').files[0]||null});resetRepairForm();await loadState();switchView('dashboard');toast('Repair ticket saved.')}catch(err){toast(err.message,'danger')}};
function resetRepairForm(){$('repairForm').reset();$('repairId').value='';$('repEstimate').value=0;$('repFinal').value=0;$('repairFormTitle').textContent='Create repair ticket';$('repairPhotoPreviewWrap').classList.add('hidden');$('repairPhotoPreview').removeAttribute('src');$('repairPhotoPreviewCaption').textContent='';}$('resetRepair').onclick=resetRepairForm;$('repPhoto').addEventListener('change',()=>{let f=$('repPhoto').files[0];if(!f){$('repairPhotoPreviewWrap').classList.add('hidden');return;}if(!/^image\/(jpeg|png|webp)$/.test(f.type)||f.size>3*1024*1024){toast('Choose JPG, PNG or WEBP up to 3 MB.','warning');$('repPhoto').value='';$('repairPhotoPreviewWrap').classList.add('hidden');return;}let reader=new FileReader();reader.onload=()=>{$('repairPhotoPreview').src=reader.result;$('repairPhotoPreviewCaption').textContent=f.name;$('repairPhotoPreviewWrap').classList.remove('hidden');};reader.readAsDataURL(f);});
function editRepair(id){let r=state.repairs.find(x=>Number(x.id)===id);if(!r)return;$('repairId').value=r.id;$('repName').value=r.customer_name;$('repPhone').value=r.customer_phone;$('repModel').value=r.device_model;$('repDescription').value=r.description;$('repEstimate').value=r.estimated_cost;$('repFinal').value=r.final_cost;$('repDue').value=r.due_date||'';$('repairFormTitle').textContent='Edit repair ticket';if(r.device_photo){$('repairPhotoPreview').src=r.device_photo;$('repairPhotoPreviewCaption').textContent='Current saved photo (choose a new image to replace it)';$('repairPhotoPreviewWrap').classList.remove('hidden');}else{$('repairPhotoPreviewWrap').classList.add('hidden');}switchView('repairs');$('repairForm').scrollIntoView({behavior:'smooth',block:'center'});}
async function changeStatus(id,status){try{await api('repair_status',{id,status});await loadState();toast('Repair status updated.')}catch(e){toast(e.message,'danger')}}
async function deleteRepair(id){if(!confirm('Delete this repair ticket and its payment history?'))return;try{await api('repair_delete',{id});await loadState();toast('Repair deleted.')}catch(e){toast(e.message,'danger')}}
const paymentModal=new bootstrap.Modal($('paymentModal'));function openPayment(id){let r=state.repairs.find(x=>Number(x.id)===id);if(!r)return;$('paymentRepairId').value=id;$('paymentAmount').value=Math.max(0,Number(r.final_cost)-state.payments.filter(p=>Number(p.repair_id)===id).reduce((a,p)=>a+Number(p.amount),0));paymentModal.show();}$('paymentForm').onsubmit=async e=>{e.preventDefault();try{await api('repair_payment',{repair_id:$('paymentRepairId').value,amount:$('paymentAmount').value,method:$('paymentMethod').value,note:$('paymentNote').value});paymentModal.hide();await loadState();toast('Repair payment recorded.')}catch(err){toast(err.message,'danger')}};
async function invoice(id){let r=state.repairs.find(x=>Number(x.id)===id);if(!r)return;let s=state.shop;$('invoiceLogo').src=s.logo_path||placeholder;$('invoiceShop').textContent=s.shop_name;$('invoicePhone').textContent=s.phone;$('invoiceDate').textContent='Ticket #'+r.id+' · '+dateFmt(r.created_at);if(r.device_photo){$('invoicePhoto').src=r.device_photo;$('invoicePhotoWrap').classList.remove('hidden');try{await $('invoicePhoto').decode();}catch(e){}}else{$('invoicePhotoWrap').classList.add('hidden');$('invoicePhoto').removeAttribute('src');}$('invoiceRows').innerHTML=[['Customer',r.customer_name],['Phone',r.customer_phone],['Device',r.device_model],['Problem / work required',r.description],['Status',r.status],['Payment status',r.payment_status],['Estimated bill',fmt(r.estimated_cost)],['Final bill',fmt(r.final_cost)]].map(([a,b])=>`<tr><th style="width:32%">${esc(a)}</th><td>${esc(b)}</td></tr>`).join('');$('invoiceTotal').textContent='Total bill: '+fmt(r.final_cost);let el=$('invoiceTemplate');el.classList.remove('hidden');try{await html2pdf().set({margin:8,filename:`RepairFlow_Invoice_${r.id}.pdf`,image:{type:'jpeg',quality:.96},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(el).save();}catch(e){toast('Invoice PDF could not be generated. Check your connection and try again.','danger')}finally{el.classList.add('hidden')}let digits=String(r.customer_phone).replace(/\D/g,'');if(digits){let msg=encodeURIComponent(`Assalam-o-Alaikum ${r.customer_name}, your repair ticket #${r.id} for ${r.device_model} at ${s.shop_name} is ${r.status}. Bill: Rs. ${r.final_cost}. Payment status: ${r.payment_status}.`);window.open(`https://wa.me/${digits}?text=${msg}`,'_blank','noopener');}}
$('settingsForm').onsubmit=async e=>{e.preventDefault();try{await api('settings',{shop_name:$('settingsName').value,phone:$('settingsPhone').value},{logo:$('settingsLogo').files[0]||null});await loadState();toast('Shop branding saved.')}catch(err){toast(err.message,'danger')}};
$('aiForm').onsubmit=e=>{e.preventDefault();let q=$('aiPrompt').value.toLowerCase(),out='';let low=state.products.filter(p=>Number(p.qty)<=Number(p.low_stock_threshold));let late=state.repairs.filter(r=>['Pending','In-Progress'].includes(r.status)&&r.due_date&&r.due_date<new Date().toISOString().slice(0,10));let pending=state.repairs.filter(r=>['Pending','In-Progress'].includes(r.status));let sales=state.sales.reduce((a,x)=>a+Number(x.total||0),0),billed=state.repairs.reduce((a,x)=>a+Number(x.final_cost||0),0);if(q.includes('stock')||q.includes('inventory')){out=low.length?`<strong>Stock alerts (${low.length})</strong><ul class="mt-2">${low.map(p=>`<li>${esc(p.title)} — ${Number(p.qty)} available; threshold ${Number(p.low_stock_threshold)}. ${Number(p.qty)===0?'Restock required.':'Consider replenishment.'}</li>`).join('')}</ul>`:'<strong class="text-success">No low-stock alerts. Inventory is above configured thresholds.</strong>';}else if(q.includes('delay')||q.includes('overdue')||q.includes('late')){out=late.length?`<strong>Overdue repairs (${late.length})</strong><ul class="mt-2">${late.map(r=>`<li>${esc(r.customer_name)} — ${esc(r.device_model)}, due ${esc(r.due_date)}.</li>`).join('')}</ul>`:'No overdue repair tickets found. Check due dates are set for repairs.';}else if(q.includes('revenue')||q.includes('report')||q.includes('earning')||q.includes('sale')){out=`<strong>Recorded business summary</strong><ul class="mt-2"><li>Repair bills: ${fmt(billed)}</li><li>Inventory sales: ${fmt(sales)}</li><li>Combined billed/sales total: ${fmt(billed+sales)}</li><li>Repair tickets: ${state.repairs.length}; inventory sale transactions: ${state.sales.length}</li></ul><span class="small-muted">Repair bills are billed totals, not necessarily fully collected payments.</span>`;}else if(q.includes('pending')||q.includes('repair')||q.includes('workload')){out=`<strong>Repair workload</strong><ul class="mt-2"><li>Open repairs: ${pending.length}</li><li>Pending: ${state.repairs.filter(r=>r.status==='Pending').length}</li><li>In progress: ${state.repairs.filter(r=>r.status==='In-Progress').length}</li><li>Completed: ${state.repairs.filter(r=>r.status==='Completed').length}</li><li>Unpaid/partial tickets: ${state.repairs.filter(r=>r.payment_status!=='Paid').length}</li></ul>`;}else{out='Try asking about stock, delayed repairs, revenue summary, sales or pending repairs.';}$('aiOutput').innerHTML=out;};
$('reportDate').value=new Date().toISOString().slice(0,10);$('loadReport').onclick=generateReport;$('downloadReport').onclick=downloadReport;
async function generateReport(){try{let d=await api('report',{period:$('reportPeriod').value,date:$('reportDate').value},null,'GET');currentReport=d;renderReport(d);}catch(e){toast(e.message,'danger')}}
function renderReport(d){let s=d.summary,shop=d.shop;$('reportContent').innerHTML=`<div id="reportPaper" class="report-paper"><div style="display:flex;align-items:center;gap:14px;border-bottom:2px solid #4f46e5;padding-bottom:15px;margin-bottom:18px"><img src="${esc(shop.logo_path||placeholder)}" style="width:58px;height:58px;object-fit:cover;border-radius:10px"><div><h2 style="margin:0">${esc(shop.shop_name)}</h2><div>${esc(shop.phone)}</div><div style="color:#667085">${esc(d.period.toUpperCase())} REPORT · ${esc(d.label)}</div></div></div><div class="row g-2 mb-3"><div class="col-6 col-lg-3"><div class="border rounded p-3"><small>Repair tickets</small><h4>${s.repair_count}</h4><div>${fmt(s.repair_billed)} billed</div></div></div><div class="col-6 col-lg-3"><div class="border rounded p-3"><small>Direct sales</small><h4>${s.sales_count}</h4><div>${fmt(s.sales_total)} sold</div></div></div><div class="col-6 col-lg-3"><div class="border rounded p-3"><small>Repair payments received</small><h4>${fmt(s.payments_received)}</h4></div></div><div class="col-6 col-lg-3"><div class="border rounded p-3"><small>Combined billed / sold</small><h4>${fmt(Number(s.repair_billed)+Number(s.sales_total))}</h4></div></div></div><h5>Repair records</h5><table><thead><tr><th>Date</th><th>Customer</th><th>Device</th><th>Description</th><th>Status</th><th>Payment</th><th>Bill</th></tr></thead><tbody>${d.repairs.map(r=>`<tr><td>${esc(dateFmt(r.created_at))}</td><td>${esc(r.customer_name)}</td><td>${esc(r.device_model)}</td><td>${esc(r.description)}</td><td>${esc(r.status)}</td><td>${esc(r.payment_status)}</td><td>${fmt(r.final_cost)}</td></tr>`).join('')||'<tr><td colspan="7">No repair records in this period.</td></tr>'}</tbody></table><h5 style="margin-top:22px">Inventory sales</h5><table><thead><tr><th>Date</th><th>Product</th><th>Category</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${d.sales.map(x=>`<tr><td>${esc(dateFmt(x.created_at))}</td><td>${esc(x.product_title)}</td><td>${esc(x.category_name)}</td><td>${Number(x.quantity)}</td><td>${fmt(x.unit_price)}</td><td>${fmt(x.total)}</td></tr>`).join('')||'<tr><td colspan="6">No inventory sales in this period.</td></tr>'}</tbody></table><p style="margin-top:20px;color:#667085;font-size:11px">Generated by RepairFlow Pro · ${esc(new Date().toLocaleString())}</p></div>`;}
function downloadReport(){if(!$('reportPaper')){toast('Generate a report first.','warning');return;}let el=$('reportPaper');html2pdf().set({margin:8,filename:`RepairFlow_${currentReport?.period||'report'}_${currentReport?.label||'export'}.pdf`,image:{type:'jpeg',quality:.96},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'landscape'}}).from(el).save();}
let deferredInstallPrompt=null;const installBtn=$('installBtn');window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;installBtn.classList.remove('hidden');});installBtn.addEventListener('click',async()=>{if(!deferredInstallPrompt){toast('On iPhone, use Share → Add to Home Screen.','info');return;}deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;installBtn.classList.add('hidden');});window.addEventListener('appinstalled',()=>{installBtn.classList.add('hidden');toast('RepairFlow Pro installed.');});if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}if(/iPhone|iPad|iPod/i.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches){installBtn.classList.remove('hidden');installBtn.addEventListener('click',()=>toast('To install: tap Share in Safari, then Add to Home Screen.','info'));}
start();
</script></body></html>
